local ClockFacePainter = {}
local PRODUCTS = {
    painted_dial = { name = "Poslikana številčnica", enamelCost = 1, paintCost = 1, time = 2, cost = 25, artistry = 40, prestige = 2, description = "Poslikana številčnica za ure." },
    gilded_dial = { name = "Pozlačena številčnica", enamelCost = 1, goldCost = 1, paintCost = 1, time = 4, cost = 60, artistry = 55, prestige = 5, happiness = 1, description = "Pozlačena številčnica z rimskimi številkami." },
    enameled_dial = { name = "Emajlirana številčnica", enamelCost = 2, silverCost = 1, paintCost = 1, time = 6, cost = 140, artistry = 70, prestige = 9, happiness = 2, description = "Emajlirana številčnica za plemiče." },
    silver_moon_dial = { name = "Srebrnomesečna številčnica", enamelCost = 2, silverCost = 1, goldCost = 1, paintCost = 1, time = 9, cost = 320, artistry = 82, prestige = 15, happiness = 3, description = "Številčnica z luninimi fazami za plemiče." },
    gold_astro_dial = { name = "Zlatoastrološka številčnica", enamelCost = 2, goldCost = 1, silverCost = 1, jewelCost = 1, paintCost = 1, time = 12, cost = 700, artistry = 92, prestige = 24, happiness = 5, description = "Astrološka številčnica z zlatom za visoke plemiče." },
    royal_grand_dial = { name = "Kraljevski veliki številčnica", enamelCost = 4, goldCost = 2, silverCost = 1, jewelCost = 1, pearlCost = 1, paintCost = 2, time = 17, cost = 1800, artistry = 100, prestige = 42, happiness = 10, description = "Velika kraljevska številčnica z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Številčničarska delavnica", cost = { gold = 280, wood = 120, stone = 250 }, upkeep = 7, qualityBonus = 5 },
    enamel_room = { name = "Emajlnica", cost = { gold = 950, wood = 250, stone = 450, enamel = 8 }, upkeep = 23, qualityBonus = 18 },
    gilding_room = { name = "Pozlatnica", cost = { gold = 2300, wood = 350, stone = 700, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_dial_atelier = { name = "Kraljevski atelje številčnic", cost = { gold = 9200, wood = 600, stone = 1000, gold = 60, jewel = 20 }, upkeep = 185, qualityBonus = 55, prestigeBonus = 40 },
}
ClockFacePainter.enamelStock = 14; ClockFacePainter.paintStock = 12; ClockFacePainter.silverStock = 8; ClockFacePainter.goldStock = 6; ClockFacePainter.jewelStock = 6; ClockFacePainter.pearlStock = 4
ClockFacePainter.productStock = {}; ClockFacePainter.buildings = {}; ClockFacePainter.maker = nil; ClockFacePainter.activeMaking = {}; ClockFacePainter.totalProducts = 0; ClockFacePainter.dayTimer = 0
function ClockFacePainter.init() ClockFacePainter.enamelStock=14; ClockFacePainter.paintStock=12; ClockFacePainter.silverStock=8; ClockFacePainter.goldStock=6; ClockFacePainter.jewelStock=6; ClockFacePainter.pearlStock=4; ClockFacePainter.productStock={}; ClockFacePainter.buildings={}; ClockFacePainter.maker=nil; ClockFacePainter.activeMaking={}; ClockFacePainter.totalProducts=0; ClockFacePainter.dayTimer=0; print("[ClockFacePainter] Royal Clock Face Painter System initialized (6 products, 4 buildings)") end
function ClockFacePainter.hireMaker(n,s) s=s or math.random(50,90); local c=520+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ClockFacePainter.maker={name=n or ("Številčničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Številčničar najet: %s (spretnost: %d)",ClockFacePainter.maker.name,s),"success") end; return true end
function ClockFacePainter.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ClockFacePainter.build(id) local ok,e=ClockFacePainter.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ClockFacePainter.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ClockFacePainter.getQualityBonus() local b=0; for _,bd in ipairs(ClockFacePainter.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ClockFacePainter.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.enamelCost and ClockFacePainter.enamelStock<(d.enamelCost or 0) then return false,"Premalo emajla" end; if d.paintCost and ClockFacePainter.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.silverCost and ClockFacePainter.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ClockFacePainter.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ClockFacePainter.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ClockFacePainter.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ClockFacePainter.buildings==0 then return false,"Potrebna delavnica" end; if not ClockFacePainter.maker then return false,"Potreben številčničar" end; return true end
function ClockFacePainter.make(pt,qty) qty=qty or 1; local ok,e=ClockFacePainter.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.enamelCost then ClockFacePainter.enamelStock=ClockFacePainter.enamelStock-d.enamelCost*qty end; if d.paintCost then ClockFacePainter.paintStock=ClockFacePainter.paintStock-d.paintCost*qty end; if d.silverCost then ClockFacePainter.silverStock=ClockFacePainter.silverStock-d.silverCost*qty end; if d.goldCost then ClockFacePainter.goldStock=ClockFacePainter.goldStock-d.goldCost*qty end; if d.jewelCost then ClockFacePainter.jewelStock=ClockFacePainter.jewelStock-d.jewelCost*qty end; if d.pearlCost then ClockFacePainter.pearlStock=ClockFacePainter.pearlStock-d.pearlCost*qty end; local t=d.time; if ClockFacePainter.maker then t=math.max(1,t-math.floor(ClockFacePainter.maker.skill/12)) end; table.insert(ClockFacePainter.activeMaking,{id="clockface_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,artistry=d.artistry or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ClockFacePainter.completeMaking(m) local q=1.0+(ClockFacePainter.getQualityBonus()/100); if ClockFacePainter.maker then q=q+(ClockFacePainter.maker.skill/180) end; q=math.min(2.0,q); ClockFacePainter.productStock[m.productType]=(ClockFacePainter.productStock[m.productType] or 0)+m.quantity; ClockFacePainter.totalProducts=ClockFacePainter.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ClockFacePainter.maker then ClockFacePainter.maker.itemsMade=ClockFacePainter.maker.itemsMade+m.quantity; if math.random()<0.20 then ClockFacePainter.maker.skill=math.min(100,ClockFacePainter.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Številčnica poslikana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"clockface.completed",{productName=m.productName,artistry=m.artistry,prestige=m.prestige,happiness=m.happiness}) end end
function ClockFacePainter.update(dt) if not _G.state then return end; ClockFacePainter.dayTimer=ClockFacePainter.dayTimer+dt; if ClockFacePainter.dayTimer>=30 then ClockFacePainter.dayTimer=0; for i=#ClockFacePainter.activeMaking,1,-1 do local m=ClockFacePainter.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ClockFacePainter.completeMaking(m); table.remove(ClockFacePainter.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ClockFacePainter.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ClockFacePainter.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ClockFacePainter.getStats() return {enamelStock=ClockFacePainter.enamelStock,paintStock=ClockFacePainter.paintStock,silverStock=ClockFacePainter.silverStock,goldStock=ClockFacePainter.goldStock,jewelStock=ClockFacePainter.jewelStock,pearlStock=ClockFacePainter.pearlStock,productStock=ClockFacePainter.productStock,numBuildings=#ClockFacePainter.buildings,hasMaker=ClockFacePainter.maker~=nil,makerName=ClockFacePainter.maker and ClockFacePainter.maker.name or "—",makerSkill=ClockFacePainter.maker and ClockFacePainter.maker.skill or 0,activeMaking=#ClockFacePainter.activeMaking,totalProducts=ClockFacePainter.totalProducts} end
return ClockFacePainter
